<?php
namespace App\Controllers;
use App\Core\{Auth,View,Request,Csrf,Response,Database};use App\Services\{ClientService,PermissionService,ActivityService};use App\Repositories\ClientRepository;
final class ClientController{
 public function index():void{Auth::requireLogin();(new PermissionService)->require('Client','view');$q=trim((new Request)->input('q',''));$clients=(new ClientRepository)->all(500);if($q!=='')$clients=array_values(array_filter($clients,fn($c)=>stripos(($c['full_name']??'').' '.($c['email']??'').' '.($c['phone']??''),$q)!==false));View::render('clients/index',['clients'=>$clients,'q'=>$q]);}
 public function create():void{Auth::requireLogin();(new PermissionService)->require('Client','add');$types=Database::pdo()->query('SELECT * FROM client_types WHERE is_active=1 ORDER BY type_name')->fetchAll();$fields=Database::pdo()->query("SELECT * FROM custom_fields WHERE tenant_id=1 AND entity_type='client' AND is_active=1 ORDER BY sort_order,id")->fetchAll(); View::render('clients/form',['types'=>$types,'customFields'=>$fields]);}
 public function store():never{Auth::requireLogin();(new PermissionService)->require('Client','add');$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('Security token expired');}(new ClientService)->create($r->all());Response::redirect(route('clients'));}
 public function show($id):void{Auth::requireLogin();(new PermissionService)->require('Client','view');$client=(new ClientRepository)->findWithRelations((int)$id);if(!$client){http_response_code(404);exit('Client not found');}View::render('clients/show',['client'=>$client]);}
 public function edit($id):void{Auth::requireLogin();(new PermissionService)->require('Client','edit');$types=Database::pdo()->query('SELECT * FROM client_types WHERE is_active=1 ORDER BY type_name')->fetchAll();$client=(new ClientRepository)->find((int)$id);$values=[];$vq=Database::pdo()->prepare('SELECT field_id,value_text,value_json FROM custom_field_values WHERE entity_id=?');$vq->execute([(int)$id]);foreach($vq->fetchAll() as $v)$values[$v['field_id']]=$v['value_json']?json_decode($v['value_json'],true):$v['value_text']; $fields=Database::pdo()->query("SELECT * FROM custom_fields WHERE tenant_id=1 AND entity_type='client' AND is_active=1 ORDER BY sort_order,id")->fetchAll(); View::render('clients/form',['client'=>$client,'types'=>$types,'customFields'=>$fields,'customValues'=>$values]);}
 public function update($id):never{Auth::requireLogin();(new PermissionService)->require('Client','edit');$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('Security token expired');}(new ClientService)->update((int)$id,$r->all());Response::redirect(route('client.view',['id'=>$id]));}
 public function archive($id):never{Auth::requireLogin();(new PermissionService)->require('Client','delete');(new ClientService)->archive((int)$id);Response::redirect(route('clients'));}
 public function comment($id):never{Auth::requireLogin();(new PermissionService)->require('Client','edit');$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('Security token expired');}$text=trim((string)$r->input('comment_detail'));if($text!==''){Database::pdo()->prepare('INSERT INTO client_comments(tenant_id,client_id,comment_detail,user_id,created_at,updated_at) VALUES(1,?,?,?,NOW(),NOW())')->execute([(int)$id,$text,Auth::id()]);(new ActivityService)->record('COMMENT_ADDED','Clients','client',$id,['comment'=>$text]);}Response::redirect(route('client.view',['id'=>$id]));}
 public function commentEdit($id):never{Auth::requireLogin();(new PermissionService)->require('Client','edit');$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('Security token expired');}$pdo=Database::pdo();$s=$pdo->prepare('SELECT * FROM client_comments WHERE id=? AND deleted_at IS NULL');$s->execute([(int)$id]);$comment=$s->fetch();if(!$comment){http_response_code(404);exit('Comment not found');}$text=trim((string)$r->input('comment_detail'));if($text===''){http_response_code(422);exit('Comment cannot be empty');}$v=$pdo->prepare('SELECT COALESCE(MAX(version_no),0)+1 FROM client_comment_versions WHERE comment_id=?');$v->execute([(int)$id]);$version=(int)$v->fetchColumn();$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO client_comment_versions(comment_id,version_no,comment_detail,user_id) VALUES(?,?,?,?)')->execute([(int)$id,$version,$comment['comment_detail'],Auth::id()]);$pdo->prepare('UPDATE client_comments SET comment_detail=?,updated_at=NOW() WHERE id=?')->execute([$text,(int)$id]);$pdo->commit();(new ActivityService)->record('COMMENT_UPDATED','Clients','comment',(int)$id,['comment'=>['before'=>$comment['comment_detail'],'after'=>$text]],'stage_3');}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}Response::redirect(route('client.view',['id'=>$comment['client_id']]));}
}
